360: func (m *MemStorage) AddBatchToDB(data models.MetricsList) error {
361: 	txCtx, cancel := context.WithTimeout(m.ctx, 30*time.Second)
362: 	defer cancel()
363: 
364: 	tx, err := m.DB.BeginTx(txCtx, nil)
365: 	if err != nil {
366: 		return err
367: 	}
368: 	defer func() {
369: 		_ = tx.Rollback()
370: 	}()
371: 
372: 	stmtGauge, err := tx.PrepareContext(txCtx, `
373: 		INSERT INTO metrics (name, m_type, value, delta) VALUES ($1, 'gauge', $2, 0)
374: 		ON CONFLICT (name) DO UPDATE SET
375: 			m_type = 'gauge',
376: 			value = EXCLUDED.value,
377: 			delta = 0
378: 	`)
379: 	if err != nil {
380: 		return err
381: 	}
382: 	defer stmtGauge.Close()
383: 
384: 	stmtCounter, err := tx.PrepareContext(txCtx, `
385: 		INSERT INTO metrics (name, m_type, delta, value) VALUES ($1, 'counter', $2, 0)
386: 		ON CONFLICT (name) DO UPDATE SET
387: 			m_type = 'counter',
388: 			delta = CASE WHEN metrics.m_type = 'counter' THEN metrics.delta + EXCLUDED.delta ELSE EXCLUDED.delta END,
389: 			value = 0
390: 	`)
391: 	if err != nil {
392: 		return err
393: 	}
394: 	defer stmtCounter.Close()
395: 
396: 	for _, metric := range data {
397: 		switch metric.MType {
398: 		case models.Gauge:
399: 			_, err = stmtGauge.ExecContext(txCtx, metric.ID, *metric.Value)
400: 		case models.Counter:
401: 			_, err = stmtCounter.ExecContext(txCtx, metric.ID, *metric.Delta)
402: 		}
403: 		if err != nil {
404: 			return err
405: 		}
406: 	}
407: 
408: 	return tx.Commit()
409: }
