{"assistant_action": {"action": "edit", "edits": [{"content": "package repository

import (
	"context"
	"database/sql"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"sync"
	"time"

	"github.com/mailru/easyjson"
	models "github.com/postman17/metrics/internal/model"
)

type MetricsRepository interface {
	AddGauge(name string, value float64)
	CheckGaugeType(name string) bool
	AddCounter(name string, value int64)
	CheckCounterType(name string) bool
	GetTypeValue(name string) any
	AddBatch(data models.MetricsList) error
}

type MemStore struct {
	mu   sync.Mutex
	Data map[string]any
}

func (m *MemStore) AddGauge(name string, value float64) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.Data[name] = value
}

func (m *MemStore) CheckGaugeType(name string) bool {
	m.mu.Lock()
	defer m.mu.Unlock()
	val, ok := m.Data[name]
	_, okType := val.(float64)
	return ok && okType
}

func (m *MemStore) AddCounter(name string, value int64) {
	m.mu.Lock()
	defer m.mu.Unlock()
	oldValue, ok := m.Data[name].(int64)
	var newValue int64
	if ok {
		newValue = oldValue + value
	} else {
		newValue = value
	}
	m.Data[name] = newValue
}

func (m *MemStore) CheckCounterType(name string) bool {
	m.mu.Lock()
	defer m.mu.Unlock()
	val, ok := m.Data[name]
	_, okType := val.(int64)
	return ok && okType
}

func (m *MemStore) GetTypeValue(name string) any {
	m.mu.Lock()
	defer m.mu.Unlock()
	val, ok := m.Data[name]
	if !ok {
		return nil
	}
	return val
}

func (m *MemStore) AddBatch(data models.MetricsList) error {
	for _, metric := range data {
		if metric.ID == "" {
			return fmt.Errorf("metric id is empty")
		}
		if metric.MType != models.Gauge && metric.MType != models.Counter {
			return fmt.Errorf("invalid metric type: %s", metric.MType)
		}
		switch metric.MType {
		case models.Gauge:
			if metric.Value == nil {
				return fmt.Errorf("gauge value is nil for metric %s", metric.ID)
			}
		case models.Counter:
			if metric.Delta == nil {
				return fmt.Errorf("counter delta is nil for metric %s", metric.ID)
			}
		}
	}

	m.mu.Lock()
	defer m.mu.Unlock()
	for _, metric := range data {
		switch metric.MType {
		case models.Gauge:
			m.Data[metric.ID] = *metric.Value
		case models.Counter:
			oldValue, ok := m.Data[metric.ID].(int64)
			var newValue int64
			if ok {
				newValue = oldValue + *metric.Delta
			} else {
				newValue = *metric.Delta
			}
			m.Data[metric.ID] = newValue
		}
	}
	return nil
}

type FileStorage struct {
	*MemStore
	StoreSync bool
	FilePath  string
}

func (f *FileStorage) AddGauge(name string, value float64) {
	f.MemStore.AddGauge(name, value)
	if f.StoreSync && f.FilePath != "" {
		if err := f.SaveToFile(); err != nil {
			slog.Error("memory save to file failed", "err", err)
		}
	}
}

func (f *FileStorage) AddCounter(name string, value int64) {
	f.MemStore.AddCounter(name, value)
	if f.StoreSync && f.FilePath != "" {
		if err := f.SaveToFile(); err != nil {
			slog.Error("memory save to file failed", "err", err)
		}
	}
}

func (f *FileStorage) AddBatch(data models.MetricsList) error {
	if err := f.MemStore.AddBatch(data); err != nil {
		return err
	}
	if f.StoreSync && f.FilePath != "" {
		if err := f.SaveToFile(); err != nil {
			slog.Error("memory save to file failed", "err", err)
		}
	}
	return nil
}

func (f *FileStorage) LoadFromFile() error {
	if f.FilePath == "" {
		return fmt.Errorf("path to storage file is empty")
	}

	data, err := os.ReadFile(f.FilePath)
	if os.IsNotExist(err) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("failed to read file: %w", err)
	}

	f.MemStore.mu.Lock()
	defer f.MemStore.mu.Unlock()

	var list models.MetricsList
	if err := easyjson.Unmarshal(data, &list); err != nil {
		return fmt.Errorf("failed to unmarshal metrics: %w", err)
	}

	for _, metric := range list {
		switch metric.MType {
		case models.Counter:
			if metric.Delta != nil {
				f.MemStore.Data[metric.ID] = *metric.Delta
			}
		case models.Gauge:
			if metric.Value != nil {
				f.MemStore.Data[metric.ID] = *metric.Value
			}
		}
	}
	slog.Info("Data load from file")
	return nil
}

func (f *FileStorage) SaveToFile() error {
	f.MemStore.mu.Lock()
	list := make(models.MetricsList, 0, len(f.MemStore.Data))

	for id, v := range f.MemStore.Data {
		switch val := v.(type) {
		case float64:
			value := val
			list = append(list, models.Metrics{
				ID:    id,
				MType: models.Gauge,
				Value: &value,
			})
		case int64:
			delta := val
			list = append(list, models.Metrics{
				ID:    id,
				MType: models.Counter,
				Delta: &delta,
			})
		}
	}
	f.MemStore.mu.Unlock()

	data, err := easyjson.Marshal(list)
	if err != nil {
		return fmt.Errorf("failed to marshal metrics via easyjson: %w", err)
	}

	dir := filepath.Dir(f.FilePath)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return fmt.Errorf("failed to create directory %s: %w", dir, err)
	}

	tmpPath := f.FilePath + ".tmp"
	if err := os.WriteFile(tmpPath, data, 0644); err != nil {
		return fmt.Errorf("failed to write temp file: %w", err)
	}

	if err := os.Rename(tmpPath, f.FilePath); err != nil {
		_ = os.Remove(tmpPath)
		return fmt.Errorf("failed to rename temp file to destination: %w", err)
	}

	slog.Info("Data saved to file")

