	return fmt.Errorf("database storage is not configured")
}

func NewMemStorage(ctx context.Context, storeSync bool, filePath string, restore bool, db *sql.DB, withDB bool) *MemStorage {
	baseMem := &MemStore{
		Data: make(map[string]any),
	}

	mem := &MemStorage{
		Data:      baseMem.Data,
		StoreSync: storeSync,
		FilePath:  filePath,
		DB:        db,
		ctx:       ctx,
		WithDB:    withDB,
		memImpl:   baseMem,
	}

	if withDB {
		mem.dbImpl = &DBStorage{
			MemStore: baseMem,
			DB:       db,
			ctx:      ctx,
		}
		mem.impl = mem.dbImpl
	} else if filePath != "" {
		mem.fileImpl = &FileStorage{
			MemStore:  baseMem,
			StoreSync: storeSync,
			FilePath:  filePath,
		}
		if restore {
			if err := mem.fileImpl.LoadFromFile(); err != nil {
				slog.Error("memory load from file failed", "err", err)
			}
		}
		mem.impl = mem.fileImpl
	} else {
		mem.impl = baseMem
		if restore {
			slog.Error("memory load from file failed", "err", fmt.Errorf("path to storage file is empty"))
		}
	}

	return mem
}
