package repository

import (
	"context"
	"database/sql"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"sync"
	"time"

	"github.com/mailru/easyjson"
	models "github.com/postman17/metrics/internal/model"
)

type MetricsRepository interface {
	AddGauge(name string, value float64)
	CheckGaugeType(name string) bool
	AddCounter(name string, value int64)
	CheckCounterType(name string) bool
	GetTypeValue(name string) any
	AddBatch(data models.MetricsList) error
}

type MemoryStorage struct {
	mu   sync.Mutex
	Data map[string]any
}

func NewMemoryStorage() *MemoryStorage {
	return &MemoryStorage{
		Data: make(map[string]any),
	}
}

func (s *MemoryStorage) AddGauge(name string, value float64) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.Data[name] = value
}

func (s *MemoryStorage) CheckGaugeType(name string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	val, ok := s.Data[name]
	_, okType := val.(float64)
	return ok && okType
}

func (s *MemoryStorage) AddCounter(name string, value int64) {
	s.mu.Lock()
	defer s.mu.Unlock()
	oldValue, ok := s.Data[name].(int64)
	var newValue int64
	if ok {
		newValue = oldValue + value
	} else {
		newValue = value
	}
	s.Data[name] = newValue
}

func (s *MemoryStorage) CheckCounterType(name string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	val, ok := s.Data[name]
	_, okType := val.(int64)
	return ok && okType
}

func (s *MemoryStorage) GetTypeValue(name string) any {
	s.mu.Lock()
	defer s.mu.Unlock()
	val, ok := s.Data[name]
	if !ok {
		return nil
	}
	return val
}

func (s *MemoryStorage) AddBatch(data models.MetricsList) error {
	for _, metric := range data {
		if metric.ID == "" {
			return fmt.Errorf("metric id is empty")
		}
		if metric.MType != models.Gauge && metric.MType != models.Counter {
			return fmt.Errorf("invalid metric type: %s", metric.MType)
		}
		switch metric.MType {
		case models.Gauge:
			if metric.Value == nil {
				return fmt.Errorf("gauge value is nil for metric %s", metric.ID)
			}
		case models.Counter:
			if metric.Delta == nil {
				return fmt.Errorf("counter delta is nil for metric %s", metric.ID)
			}
		}
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	for _, metric := range data {
		switch metric.MType {
		case models.Gauge:
			s.Data[metric.ID] = *metric.Value
		case models.Counter:
			oldValue, ok := s.Data[metric.ID].(int64)
			var newValue int64
			if ok {
				newValue = oldValue + *metric.Delta
			} else {
				newValue = *metric.Delta
			}
			s.Data[metric.ID] = newValue
		}
	}
	return nil
}

type FileStorage struct {
	*MemoryStorage
	filePath  string
	storeSync bool
}

func NewFileStorage(mem *MemoryStorage, filePath string, storeSync bool) *FileStorage {
	return &FileStorage{
		MemoryStorage: mem,
		filePath:      filePath,
		storeSync:     storeSync,
	}
}

func (f *FileStorage) AddGauge(name string, value float64) {
	f.MemoryStorage.AddGauge(name, value)
	if f.storeSync && f.filePath != "" {
		if err := f.SaveToFile(); err != nil {
			slog.Error("memory save to file failed", "err", err)
		}
	}
}

func (f *FileStorage) AddCounter(name string, value int64) {
	f.MemoryStorage.AddCounter(name, value)
	if f.storeSync && f.filePath != "" {
		if err := f.SaveToFile(); err != nil {
			slog.Error("memory save to file failed", "err", err)
		}
	}
}

func (f *FileStorage) AddBatch(data models.MetricsList) error {
	if err := f.MemoryStorage.AddBatch(data); err != nil {
		return err
	}
	if f.storeSync && f.filePath != "" {
		if err := f.SaveToFile(); err != nil {
			slog.Error("memory save to file failed", "err", err)
		}
	}
	return nil
}

func (f *FileStorage) LoadFromFile() error {
	if f.filePath == "" {
		return fmt.Errorf("path to storage file is empty")
	}

	data, err := os.ReadFile(f.filePath)
	if os.IsNotExist(err) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("failed to read file: %w", err)
	}

	f.mu.Lock()
	defer f.mu.Unlock()

	var list models.MetricsList
	if err := easyjson.Unmarshal(data, &list); err != nil {
		return fmt.Errorf("failed to unmarshal metrics: %w", err)
	}

	for _, metric := range list {
		switch metric.MType {
		case models.Counter:
			if metric.Delta != nil {
				f.Data[metric.ID] = *metric.Delta
			}
		case models.Gauge:
			if metric.Value != nil {
				f.Data[metric.ID] = *metric.Value
			}
		}
	}
	slog.Info("Data load from file")
	return nil
}

func (f *FileStorage) SaveToFile() error {
	f.mu.Lock()
	list := make(models.MetricsList, 0, len(f.Data))

	for id, v := range f.Data {
		switch val := v.(type) {
		case float64:
			value := val
			list = append(list, models.Metrics{
				ID:    id,
				MType: models.Gauge,
				Value: &value,
			})
		case int64:
			delta := val
			list = append(list, models.Metrics{
				ID:    id,
				MType: models.Counter,
				Delta: &delta,
			})
		}
	}
	f.mu.Unlock()

	data, err := easyjson.Marshal(list)
	if err != nil {
		return fmt.Errorf("failed to marshal metrics via easyjson: %w", err)
	}

	dir := filepath.Dir(f.filePath)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return fmt.Errorf("failed to create directory %s: %w", dir, err)
	}

	tmpPath := f.filePath + ".tmp"
	if err := os.WriteFile(tmpPath, data, 0644); err != nil {
		return fmt.Errorf("failed to write temp file: %w", err)
	}

	if err := os.Rename(tmpPath, f.filePath); err != nil {
		_ = os.Remove(tmpPath)
		return fmt.Errorf("failed to rename temp file to destination: %w", err)
	}

	slog.Info("Data saved to file")

	return nil
}

type DBStorage struct {
	*MemoryStorage
	db  *sql.DB
	ctx context.Context
}

func NewDBStorage(mem *MemoryStorage, db *sql.DB, ctx context.Context) *DBStorage {
	return &DBStorage{
		MemoryStorage: mem,
		db:            db,
		ctx:           ctx,
	}
}

func (d *DBStorage) AddGauge(name string, value float64) {
	d.MemoryStorage.AddGauge(name, value)
	if err := d.AddGaugeToDB(name, value); err != nil {
		slog.Error("cant save to db", "err", err)
	}
}

func (d *DBStorage) AddCounter(name string, value int64) {
	d.MemoryStorage.AddCounter(name, value)
	if err := d.AddCounterToDB(name, value); err != nil {
		slog.Error("cant save to db", "err", err)
	}
}

func (d *DBStorage) AddBatch(data models.MetricsList) error {
	if err := d.MemoryStorage.AddBatch(data); err != nil {
		return err
	}
	return d.AddBatchToDB(data)
}

func (d *DBStorage) AddGaugeToDB(name string, value float64) error {
	var (
		id    int64
		mType string
	)
	getCtx, getCancel := context.WithTimeout(d.ctx, 5*time.Second)
	defer getCancel()
	row := d.db.QueryRowContext(
		getCtx, "SELECT id, m_type FROM metrics WHERE name = $1", name,
	)
	err := row.Scan(&id, &mType)
	if err != nil && err != sql.ErrNoRows {
		return err
	}
	if err == nil && mType == "gauge" {
		updateCtx, updateCancel := context.WithTimeout(d.ctx, 5*time.Second)
		defer updateCancel()
		_, err := d.db.ExecContext(
			updateCtx, "UPDATE metrics SET value = $1 WHERE id = $2",
			value, id,
		)
		if err != nil {
			return err
		}
		return nil
	} else if err == nil && mType == "counter" {
		updateCtx, updateCancel := context.WithTimeout(d.ctx, 5*time.Second)
		defer updateCancel()
		_, err := d.db.ExecContext(
			updateCtx, "UPDATE metrics SET value = $1, m_type = $2, delta = $3 WHERE id = $4",
			value, "gauge", 0, id,
		)
		if err != nil {
			return err
		}
		return nil
	}
	insertCtx, insertCancel := context.WithTimeout(d.ctx, 5*time.Second)
	defer insertCancel()
	_, err = d.db.ExecContext(
		insertCtx, "INSERT INTO metrics (name, m_type, value) VALUES ($1, $2, $3)",
		name, "gauge", value,
	)
	if err != nil {
		return err
	}
	return nil
}

func (d *DBStorage) AddCounterToDB(name string, value int64) error {
	var (
		id    int64
		mType string
		delta int64
	)
	getCtx, getCancel := context.WithTimeout(d.ctx, 5*time.Second)
	defer getCancel()
	row := d.db.QueryRowContext(
		getCtx, "SELECT id, m_type, delta FROM metrics WHERE name = $1", name,
	)
	err := row.Scan(&id, &mType, &delta)
	if err != nil && err != sql.ErrNoRows {
		return err
	}
	if err == nil && mType == "counter" {
		value = delta + value
		updateCtx, updateCancel := context.WithTimeout(d.ctx, 5*time.Second)
		defer updateCancel()
		_, err := d.db.ExecContext(
			updateCtx, "UPDATE metrics SET delta = $1 WHERE id = $2",
			value, id,
		)
		if err != nil {
			return err
		}
		return nil
	} else if err == nil && mType == "gauge" {
		updateCtx, updateCancel := context.WithTimeout(d.ctx, 5*time.Second)
		defer updateCancel()
		_, err := d.db.ExecContext(
			updateCtx, "UPDATE metrics SET delta = $1, m_type = $2, value = $3 WHERE id = $4",
			value, "counter", 0, id,
		)
		if err != nil {
			return err
		}
		return nil
	}
	insertCtx, insertCancel := context.WithTimeout(d.ctx, 5*time.Second)
	defer insertCancel()
	_, err = d.db.ExecContext(
		insertCtx, "INSERT INTO metrics (name, m_type, delta) VALUES ($1, $2, $3)",
		name, "counter", value,
	)
	if err != nil {
		return err
	}
	return nil
}

func (d *DBStorage) AddBatchToDB(data models.MetricsList) error {
	txCtx, cancel := context.WithTimeout(d.ctx, 30*time.Second)
	defer cancel()

	tx, err := d.db.BeginTx(txCtx, nil)
	if err != nil {
		return err
	}
	defer func() {
		_ = tx.Rollback()
	}()

	stmtGauge, err := tx.PrepareContext(txCtx, `
		INSERT INTO metrics (name, m_type, value, delta) VALUES ($1, 'gauge', $2, 0)
		ON CONFLICT (name) DO UPDATE SET
			m_type = 'gauge',
			value = EXCLUDED.value,
			delta = 0
	`)
	if err != nil {
		return err
	}
	defer stmtGauge.Close()

	stmtCounter, err := tx.PrepareContext(txCtx, `
		INSERT INTO metrics (name, m_type, delta, value) VALUES ($1, 'counter', $2, 0)
		ON CONFLICT (name) DO UPDATE SET
			m_type = 'counter',
			delta = CASE WHEN metrics.m_type = 'counter' THEN metrics.delta + EXCLUDED.delta ELSE EXCLUDED.delta END,
			value = 0
	`)
	if err != nil {
		return err
	}
	defer stmtCounter.Close()

	for _, metric := range data {
		switch metric.MType {
		case models.Gauge:
			_, err = stmtGauge.ExecContext(txCtx, metric.ID, *metric.Value)
		case models.Counter:
			_, err = stmtCounter.ExecContext(txCtx, metric.ID, *metric.Delta)
		}
		if err != nil {
			return err
		}
	}

	return tx.Commit()
}

type MemStorage struct {
	repo MetricsRepository
	file *FileStorage
}

