}

func (m *MemStorage) GetTypeValue(name string) any {
	return m.repo.GetTypeValue(name)
}

func (m *MemStorage) AddBatch(data models.MetricsList) error {
	return m.repo.AddBatch(data)
}

func (m *MemStorage) SaveToFile() error {
	if m.file != nil {
		return m.file.SaveToFile()
	}
	return nil
}

func (m *MemStorage) LoadFromFile() error {
	if m.file != nil {
		return m.file.LoadFromFile()
	}
	return nil
}

func NewMemStorage(ctx context.Context, storeSync bool, filePath string, restore bool, db *sql.DB, withDB bool) *MemStorage {
	baseMem := NewMemoryStorage()
	fileRepo := NewFileStorage(baseMem, filePath, storeSync)

	var repo MetricsRepository
	if withDB {
		repo = NewDBStorage(baseMem, db, ctx)
		} else {
			repo = fileRepo
		}

	mem := &MemStorage{
		repo: repo,
		file: fileRepo,
	}

	if restore {
		if err := fileRepo.LoadFromFile(); err != nil {
			slog.Error("memory load from file failed", "err", err)
		}
	}

	return mem
}

