type MemoryStorage struct {
	mu   sync.Mutex
	Data map[string]any
}

func NewMemoryStorage() *MemoryStorage {
	return &MemoryStorage{
		Data: make(map[string]any),
	}
}

func (s *MemoryStorage) AddGauge(name string, value float64) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.Data[name] = value
}

func (s *MemoryStorage) CheckGaugeType(name string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	val, ok := s.Data[name]
	_, okType := val.(float64)
	return ok && okType
}

func (s *MemoryStorage) AddCounter(name string, value int64) {
	s.mu.Lock()
	defer s.mu.Unlock()
	oldValue, ok := s.Data[name].(int64)
	var newValue int64
	if ok {
