func (d *DBStorage) AddGaugeToDB(name string, value float64) error {
	var (
		id    int64
		mType string
	)
	getCtx, getCancel := context.WithTimeout(d.ctx, 5*time.Second)
	defer getCancel()
	row := d.db.QueryRowContext(
		getCtx, "SELECT id, m_type FROM metrics WHERE name = $1", name,
	)
	err := row.Scan(&id, &mType)
	if err != nil && err != sql.ErrNoRows {
		return err
	}
	if err == nil && mType == "gauge" {
		updateCtx, updateCancel := context.WithTimeout(d.ctx, 5*time.Second)
		defer updateCancel()
		_, err := d.db.ExecContext(
			updateCtx, "UPDATE metrics SET value = $1 WHERE id = $2",
			value, id,
		)
		if err != nil {
			return err
		}
		return nil
	} else if err == nil && mType == "counter" {
		updateCtx, updateCancel := context.WithTimeout(d.ctx, 5*time.Second)
		defer updateCancel()
		_, err := d.db.ExecContext(
			updateCtx, "UPDATE metrics SET value = $1, m_type = $2, delta = $3 WHERE id = $4",
			value, "gauge", 0, id,
		)
		if err != nil {
			return err
		}
		return nil
	}
	insertCtx, insertCancel := context.WithTimeout(d.ctx, 5*time.Second)
	defer insertCancel()
	_, err = d.db.ExecContext(
		insertCtx, "INSERT INTO metrics (name, m_type, value) VALUES ($1, $2, $3)",
		name, "gauge", value,
	)
	if err != nil {
		return err
	}
	return nil
}

func (d *DBStorage) AddCounterToDB(name string, value int64) error {
	var (
		id    int64
		mType string
		delta int64
	)
	getCtx, getCancel := context.WithTimeout(d.ctx, 5*time.Second)
	defer getCancel()
	row := d.db.QueryRowContext(
		getCtx, "SELECT id, m_type, delta FROM metrics WHERE name = $1", name,
	)
	err := row.Scan(&id, &mType, &delta)
	if err != nil && err != sql.ErrNoRows {
		return err
	}
	if err == nil && mType == "counter" {
		value = delta + value
		updateCtx, updateCancel := context.WithTimeout(d.ctx, 5*time.Second)
		defer updateCancel()
		_, err := d.db.ExecContext(
			updateCtx, "UPDATE metrics SET delta = $1 WHERE id = $2",
			value, id,
		)
		if err != nil {
			return err
		}
		return nil
	} else if err == nil && mType == "gauge" {
		updateCtx, updateCancel := context.WithTimeout(d.ctx, 5*time.Second)
		defer updateCancel()
		_, err := d.db.ExecContext(
			updateCtx, "UPDATE metrics SET delta = $1, m_type = $2, value = $3 WHERE id = $4",
			value, "counter", 0, id,
		)
		if err != nil {
			return err
		}
		return nil
	}
	insertCtx, insertCancel := context.WithTimeout(d.ctx, 5*time.Second)
	defer insertCancel()
	_, err = d.db.ExecContext(
		insertCtx, "INSERT INTO metrics (name, m_type, delta) VALUES ($1, $2, $3)",
		name, "counter", value,
	)
	if err != nil {
		return err
	}
	return nil
}

func (d *DBStorage) AddBatchToDB(data models.MetricsList) error {
	txCtx, cancel := context.WithTimeout(d.ctx, 30*time.Second)
	defer cancel()

	tx, err := d.db.BeginTx(txCtx, nil)
	if err != nil {
		return err
	}
	defer func() {
		_ = tx.Rollback()
	}()

	stmtGauge, err := tx.PrepareContext(txCtx, `
		INSERT INTO metrics (name, m_type, value, delta) VALUES ($1, 'gauge', $2, 0)
		ON CONFLICT (name) DO UPDATE SET
			m_type = 'gauge',
			value = EXCLUDED.value,
			delta = 0
	`)
	if err != nil {
		return err
	}
	defer stmtGauge.Close()

	stmtCounter, err := tx.PrepareContext(txCtx, `
		INSERT INTO metrics (name, m_type, delta, value) VALUES ($1, 'counter', $2, 0)
		ON CONFLICT (name) DO UPDATE SET
			m_type = 'counter',
			delta = CASE WHEN metrics.m_type = 'counter' THEN metrics.delta + EXCLUDED.delta ELSE EXCLUDED.delta END,
			value = 0
	`)
	if err != nil {
		return err
	}
	defer stmtCounter.Close()

	for _, metric := range data {
		switch metric.MType {
		case models.Gauge:
			_, err = stmtGauge.ExecContext(txCtx, metric.ID, *metric.Value)
		case models.Counter:
			_, err = stmtCounter.ExecContext(txCtx, metric.ID, *metric.Delta)
		}
		if err != nil {
			return err
		}
	}

	return tx.Commit()
}

