481: func NewMemStorage(ctx context.Context, storeSync bool, filePath string, restore bool, db *sql.DB, withDB bool) *MemStorage {
482: 	baseMem := NewMemoryStorage()
483: 	fileRepo := NewFileStorage(baseMem, filePath, storeSync)
484: 
485: 	var repo MetricsRepository
486: 	if withDB {
487: 		repo = NewDBStorage(baseMem, db, ctx)
488: 	} else {
489: 		repo = fileRepo
490: 	}
491: 	mem := &MemStorage{
492: 		repo: repo,
493: 		file: fileRepo,
494: 	}
495: 
496: 	if restore {
497: 		if err := fileRepo.LoadFromFile(); err != nil {
498: 			slog.Error("memory load from file failed", "err", err)
499: 		}
500: 	}
501: 
502: 	return mem
503: }
